#!/bin/sh
# Autogenerated test: runs inside a container built from each compatibility image with opentofu installed with the
# default option (version latest), as the image's remote user. POSIX sh, because alpine:3.24 ships no bash.
set -eu

# The path is computed from $0 at run time, so shellcheck cannot follow it.
# shellcheck source=/dev/null
. "$(dirname "$0")/checks.sh"

# Before tofu runs at all: every tofu run creates ~/.terraform.d, so it cannot pass as written by the install. A .gnupg
# directory may exist only empty: opensuse/leap:16.0 ships an empty /root/.gnupg.
no_opentofu_files_in_homes() {
  for no_opentofu_files_home in "${HOME}" /root; do
    for no_opentofu_files_path in .terraform.d .terraformrc .tofurc; do
      if as_root test -e "${no_opentofu_files_home}/${no_opentofu_files_path}"; then
        printf '  found: %s/%s\n' "${no_opentofu_files_home}" "${no_opentofu_files_path}"
        return 1
      fi
    done
    no_opentofu_files_gnupg="$(as_root sh -c "${FILES_UNDER}" sh "${no_opentofu_files_home}/.gnupg")" || return 1
    if [ -n "${no_opentofu_files_gnupg}" ]; then
      printf '  found:\n%s\n' "${no_opentofu_files_gnupg}"
      return 1
    fi
  done
}
check "neither home holds .terraform.d, .terraformrc, or .tofurc, or a .gnupg directory that holds a file" \
  no_opentofu_files_in_homes

no_tofu_variables() {
  no_tofu_variables_set="$(env | grep -E '^(TF|TOFU)_' || true)"
  if [ -n "${no_tofu_variables_set}" ]; then
    printf '  set: %s\n' "${no_tofu_variables_set}"
    return 1
  fi
}
check "no environment variable starting with TF_ or TOFU_ is set" no_tofu_variables
check "terraform does not resolve on PATH" sh -c '! command -v terraform'

# Computed at run time: the default option installs whatever release the latest-release link names.
latest="$(latest_release)"

check "command -v tofu resolves to /usr/local/bin/tofu" tofu_resolves_to_usr_local_bin
# By mode, not `test -x`: the test runs as root on most images, and root passes `test -x` with any execute bit.
tofu_executable_by_every_user() {
  tofu_mode="$(stat -c '%a %U' /usr/local/bin/tofu)" || return 1
  printf '  mode and owner: %s\n' "${tofu_mode}"
  [ "${tofu_mode}" = "755 root" ]
}
check "/usr/local/bin/tofu is executable by every user" tofu_executable_by_every_user
check "tofu version reports the release the latest-release link names" tofu_reports_version "${latest}"

# A configuration that declares only a constant output needs no provider and no network.
configuration_without_providers() {
  configuration_dir="$(mktemp -d)" || return 1
  printf 'output "greeting" {\n  value = "hello from opentofu"\n}\n' >"${configuration_dir}/main.tf"
  configuration_output="$(
    cd "${configuration_dir}" \
      && isolated_tofu init -input=false >/dev/null \
      && isolated_tofu apply -auto-approve -input=false >/dev/null \
      && isolated_tofu output -raw greeting
  )" || return 1
  rm -rf "${configuration_dir}"
  printf "  output: '%s'\n" "${configuration_output}"
  [ "${configuration_output}" = "hello from opentofu" ]
}
check "tofu init, apply, and output run a configuration without providers" configuration_without_providers

prerequisites_on_path() {
  for prerequisites_command in curl gpg tar gzip; do
    if ! command -v "${prerequisites_command}" >/dev/null 2>&1; then
      printf '  %s is not on PATH\n' "${prerequisites_command}"
      return 1
    fi
  done
}
check "curl, gpg, tar, and gzip are on PATH after the install" prerequisites_on_path
check "the package managers' caches hold no package index or downloaded package" package_caches_clean
check "no temporary directory or staged file of the install remains" no_install_leftovers

reportResults
